use std::{process::{Command,Stdio,Child,ChildStdin,ChildStdout},io::{Read,Write},cell::Cell};
struct Link{child:Child,input:ChildStdin,output:ChildStdout,time:Cell<u64>,sequence:u32,transactions:u32}
impl Link{
 fn start(server:&str,stderr:&str,cycles:&str)->Self{let log=std::fs::File::create(stderr).unwrap();let mut child=Command::new("wsl.exe").args(["-d","MRS-HDL-Research","--",server,cycles]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::from(log)).spawn().unwrap();let input=child.stdin.take().unwrap();let output=child.stdout.take().unwrap();Self{child,input,output,time:Cell::new(0),sequence:0,transactions:0}}
 fn request(&mut self,op:u32,address:u32,value:u32)->Result<u32,local::Error>{self.sequence=self.sequence.checked_add(1).ok_or(local::Error::Sequence)?;let fields=[0x43535231,self.sequence,op,address,value];let mut b=[0u8;20];for(i,v)in fields.iter().enumerate(){b[i*4..i*4+4].copy_from_slice(&v.to_le_bytes())}self.input.write_all(&b).map_err(|_|local::Error::Io)?;self.input.flush().map_err(|_|local::Error::Io)?;let mut reply=[0u8;24];self.output.read_exact(&mut reply).map_err(|_|local::Error::Io)?;let mut words=[0u32;6];for i in 0..6{words[i]=u32::from_le_bytes(reply[i*4..i*4+4].try_into().unwrap())}if words[0]!=0x43535231||words[1]!=self.sequence||words[2]!=0{return Err(local::Error::Io)}self.time.set(words[4]as u64|((words[5]as u64)<<32));self.transactions+=1;Ok(words[3])}
}
impl local::Bus for Link{fn read(&mut self,o:u32)->Result<u32,local::Error>{self.request(1,o,0)}fn write(&mut self,o:u32,v:u32)->Result<(),local::Error>{self.request(2,o,v).map(|_|())}fn now(&self)->u64{self.time.get()}fn yield_now(&mut self){self.request(3,1000,0).expect("RTL advance");}}
fn main(){let args:Vec<String>=std::env::args().collect();assert_eq!(args.len(),4);let mut link=Link::start(&args[1],&args[2],&args[3]);let mut endpoint=hud::Hud::new(131072).unwrap();let result=local::run(&mut link,&mut endpoint);match result{Ok((report,_completion))=>{assert_eq!((report.frames,report.accepted,report.presented,report.rejected),(2,2,2,0));assert_eq!((report.words_written,report.words_verified),(42240,42240));println!("ACTUAL_CORE_REPORT {:?}",report);let reads=link.request(4,0,0).unwrap();let writes=link.request(4,1,0).unwrap();let refresh=link.request(4,2,0).unwrap();assert!(reads>0&&writes>0&&refresh>0);println!("PLATFORM_STATS reads={} writes={} refreshes={} virtual_us={} RPC_calls={}",reads,writes,refresh,link.time.get(),link.transactions);link.request(0,0,0).unwrap();assert!(link.child.wait().unwrap().success());println!("SDK_RTL_COSIM_PASS actual_v35_core=1 actual_native_HU_endpoint=1 actual_CU71_CSR=1 actual_receiver_decoder=1 checked_SDRAM_pin_model=1 accepted=2 presented=2 rejected=0 HUD_words_written=42240 HUD_words_verified=42240 physical_SPI=0 native_CPU_outside_HDL=1");},Err(e)=>{eprintln!("SDK_RTL_COSIM_FAIL reason={:?} virtual_us={} RPC_calls={} native_stats={:?}",e,link.time.get(),link.transactions,endpoint.stats());let _=link.child.kill();let _=link.child.wait();std::process::exit(1)}}}
